return ['domain'=>'zinn-cache-pro','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'ne_NP','project-id-version'=>'zinn-cache-pro','pot-creation-date'=>'2026-09-02T07:33:51+00:00','po-revision-date'=>'2026-09-02T07:33:51+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Cache Engine'=>'Zinn® Cache Engine','https://zinndigital.com/wordpress-plugins/zinn-cache-pro'=>'https://zinndigital.com/wordpress-plugins/zinn-cache-pro','A complete caching and optimisation engine for WordPress: full-page cache, object cache, database cleanup and CSS/JS optimisation. Install this when your host does not provide a cache layer of its own — on Zinn Digital® hosting install Zinn® Cache instead. Full-page caching requires a LiteSpeed or OpenLiteSpeed server with the LSCache module. A GPLv3 fork of the LiteSpeed Cache plugin.'=>'WordPress को लागि पूर्ण क्यासिङ र अप्टिमाइजेसन इन्जिन: फुल-पेज क्यास, अब्जेक्ट क्यास, डेटाबेस क्लिनअप र CSS/JS अप्टिमाइजेसन। जब तपाईँको होस्टले आफ्नै क्यास लेयर प्रदान गर्दैन तब यसलाई इन्स्टल गर्नुहोस् — Zinn Digital® होस्टिंगमा यसको सट्टामा Zinn® Cache इन्स्टल गर्नुहोस्। फुल-पेज क्यासिङका लागि LSCache माड्युल सहितको LiteSpeed वा OpenLiteSpeed सर्भर आवश्यक पर्दछ। LiteSpeed Cache प्लगइनको GPLv3 फर्क (fork)।','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','%d hours'=>'%d घण्टा','%d hour'=>'%d घण्टा','%d minutes'=>'%d मिनेट','%d minute'=>'%d मिनेट','Purged All!'=>'सबै हटाइयो!','Purged the blog!'=>'ब्लग सफा गरियो!','Purged the URL!'=>'URL हटाइयो!','Purged!'=>'हटाइयो!','Failed to upgrade.'=>'upgrade गर्न असफल भयो।','Upgraded successfully.'=>'सफलतापूर्वक स्तरवृद्धि गरियो।','Dashboard'=>'ड्यासबोर्ड','OptimaX'=>'OptimaX','Presets'=>'प्रिसेटहरू','General'=>'सामान्य','Cache'=>'क्यास','CDN'=>'CDN','Image Optimization'=>'छवि अप्टिमाइजेसन','Page Optimization'=>'पृष्ठ अप्टिमाइजेसन','Database'=>'डेटाबेस','Crawler'=>'क्रॉलर','Toolbox'=>'उपकरणहरू','Cookie Name'=>'कुकी